writing.exampleCode:
fn main() {
    let mut tags = Vec::new();
    tags.push("rust");
    let mut count = tags.len();
    count += 1;

    let input = "  42 ";
    let input: i32 = input.trim().parse().expect("a literal number");
    println!("{tags:?} {count} {}", input + 1);
}

